/* Service worker: caches the whole app on first visit so it works offline.
 * The list of files (and a version hash) comes from precache-manifest.json,
 * which is generated by the build. */
'use strict';

const PREFIX = 'pg-wasm-';

self.addEventListener('install', (event) => {
	event.waitUntil((async () => {
		const manifest = await (await fetch('precache-manifest.json', { cache: 'no-store' })).json();
		const cache = await caches.open(PREFIX + manifest.version);
		// Add in small batches, so one failure doesn't hide which file failed.
		const files = manifest.files;
		for (let i = 0; i < files.length; i += 20) await cache.addAll(files.slice(i, i + 20));
		await self.skipWaiting();
	})());
});

self.addEventListener('activate', (event) => {
	event.waitUntil((async () => {
		const manifest = await (await fetch('precache-manifest.json', { cache: 'no-store' })).json().catch(() => null);
		if (manifest) {
			for (const key of await caches.keys())
				if (key.startsWith(PREFIX) && key !== PREFIX + manifest.version && key !== RUNTIME_CACHE) await caches.delete(key);
		}
		await self.clients.claim();
	})());
});

// Problem library files (local copy or GitHub) are cached when first used, so
// problems that have been opened once also work offline.
const RUNTIME_CACHE = PREFIX + 'library';
const isLibraryFile = (url) =>
	url.pathname.includes('/opl/') || url.hostname === 'raw.githubusercontent.com';

self.addEventListener('fetch', (event) => {
	if (event.request.method !== 'GET') return;
	event.respondWith((async () => {
		const cached = await caches.match(event.request, { ignoreSearch: true });
		if (cached) return cached;
		const response = await fetch(event.request);
		if (response.ok && isLibraryFile(new URL(event.request.url))) {
			const cache = await caches.open(RUNTIME_CACHE);
			cache.put(event.request, response.clone());
		}
		return response;
	})());
});
